def numIslands(grid):
    def dfs(i, j):
        if not (0 <= i < len(grid) and 0 <= j < len(grid[0])):
            return
        if grid[i][j] != '1': return   # 水或已淹
        grid[i][j] = '0'               # 原地标记
        for x, y in ((1,0),(-1,0),(0,1),(0,-1)):
            dfs(i + x, j + y)
    cnt = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                cnt += 1
                dfs(i, j)              # 淹整座岛
    return cnt

def maxAreaOfIsland(grid):
    def dfs(i, j):
        if not (0 <= i < len(grid) and 0 <= j < len(grid[0])):
            return 0
        if grid[i][j] != 1: return 0    # 水或已访问
        grid[i][j] = 0                  # 原地标记
        return 1 + dfs(i+1,j) + dfs(i-1,j) + dfs(i,j+1) + dfs(i,j-1)
    ans = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                ans = max(ans, dfs(i, j))
    return ans
